class Solution {
public:
    bool checkOverlap(int radius, int xCenter, int yCenter, int x1, int y1, int x2, int y2) {
        long long cx = max((long long)x1, min((long long)x2, (long long)xCenter));
        long long cy = max((long long)y1, min((long long)y2, (long long)yCenter));
        long long dx = cx - xCenter;
        long long dy = cy - yCenter;
        return dx * dx + dy * dy <= (long long)radius * radius;
    }
};
